WITH exploded AS (SELECT id, service, latency_ms, status_code, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, attr_value) SELECT id, service, latency_ms, key, attr_value, LAG(status_code) OVER (PARTITION BY service, key ORDER BY status_code, id, key) AS prev_status_code, LEAD(latency_ms) OVER (PARTITION BY service, key ORDER BY status_code, id, key) AS next_latency_ms, ROW_NUMBER() OVER (PARTITION BY service, key ORDER BY status_code, id, key) AS event_seq, ROW_NUMBER() OVER (PARTITION BY key ORDER BY status_code DESC, id, key) AS event_seq_2 FROM exploded;
